smart.css:
.smc-root h2{font-family:var(--smc-font-heading);font-size:1.35rem;margin:28px 0 12px;padding-left:10px;border-left:4px solid var(--smc-accent);color:var(--smc-text)}.smc-root h2:first-child{margin-top:0}.smc-root p{line-height:1.6}.smc-lead{color:var(--smc-muted)}.smc-cards{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px;list-style:none}.smc-cards li{background:var(--smc-surface);border:1px solid var(--smc-border);border-radius:var(--smc-radius);padding:14px;border-top:3px solid var(--smc-primary)}.smc-cards h3{font-size:1rem;margin-bottom:6px;color:var(--smc-primary)}.smc-cards p{font-size:.92rem}.smc-pics{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:16px}.smc-pics img,.smc-single{width:100%;height:auto;border-radius:var(--smc-radius);border:1px solid var(--smc-border);display:block}.smc-single{max-width:420px;margin:16px auto 0}.smc-uses{list-style:none}.smc-uses li{position:relative;padding:10px 10px 10px 36px;border-bottom:1px solid var(--smc-border);line-height:1.5}.smc-uses li:before{content:"✓";position:absolute;left:8px;top:10px;width:20px;height:20px;border-radius:50%;background:var(--smc-primary);color:var(--smc-bg);font-size:.8rem;text-align:center;line-height:20px}.smc-spec{width:100%;border-collapse:collapse;border:1px solid var(--smc-border)}.smc-spec th,.smc-spec td{padding:10px 12px;text-align:left;border-bottom:1px solid var(--smc-border);vertical-align:top}.smc-spec th{background:var(--smc-surface);width:42%;font-weight:600}@container smc (max-width:480px){.smc-cards{grid-template-columns:1fr}.smc-spec th{width:45%}}

.smc-stats{list-style:none;display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:8px}.smc-stats li{background:var(--smc-surface);border:1px solid var(--smc-border);border-radius:var(--smc-radius);padding:12px;text-align:center}.smc-stats strong{display:block;font-size:1.05rem;color:var(--smc-primary);margin-bottom:4px}.smc-stats span{font-size:.85rem;color:var(--smc-muted)}@container smc (max-width:480px){.smc-stats{grid-template-columns:1fr 1fr}}

.smc-related{list-style:none;display:grid;grid-template-columns:1fr 1fr;gap:10px}.smc-related a{display:block;height:100%;background:var(--smc-surface);border:1px solid var(--smc-border);border-left:3px solid var(--smc-accent);border-radius:var(--smc-radius);padding:12px;color:inherit;text-decoration:none}.smc-related strong{display:block;color:var(--smc-primary);margin-bottom:4px;line-height:1.35}.smc-related span{display:block;font-size:.88rem;color:var(--smc-muted);line-height:1.45}.smc-related a:hover strong{text-decoration:underline}@container smc (max-width:480px){.smc-related{grid-template-columns:1fr}}

